-- Approval steps were replaced by one review (#681) and removed with the Card cutover (#684): a review is a row of
-- work_reviews under row-level security, decided once with decide_review.
select json_build_object('steps_gone',to_regclass('public.approval_steps') is null and to_regprocedure('public.decide_approval(uuid,bigint,text,text,boolean,boolean)') is null,'reviews',to_regclass('public.work_reviews') is not null,'decision',to_regprocedure('public.decide_review(uuid,bigint,bigint,text,text)') is not null,'rls',(select relrowsecurity from pg_class where oid=to_regclass('public.work_reviews')));
